@push('styles')
<style>
  .laut {
    position: relative;
    border-radius: 16px;
    padding: 12px;
    background:
      radial-gradient(rgba(255,255,255,.07) 1px, transparent 1.5px) 0 0 / 26px 26px,
      radial-gradient(ellipse at 35% 45%, #1c5d73 0%, #0f3b4c 55%, #0a2a37 100%);
  }
  
  svg { display: block; width: 100%; height: auto; }

  .provinsi { cursor: pointer; outline: none; }
  
  .provinsi use {
    fill: var(--warna);
    stroke: rgba(10, 42, 55, .55);
    stroke-width: .6;
    stroke-linejoin: round;
    transition: filter .15s;
  }
  
  .provinsi:hover use, .provinsi:focus-visible use { filter: brightness(1.18); }
</style>
@endpush



@push('scripts')
<script>
const dataBudaya = {
    "aceh": { nama: "Aceh" },
    "sumatera-utara": { nama: "Sumatera Utara" },
    "sumatera-barat": { nama: "Sumatera Barat" },
    "riau": { nama: "Riau" },
    "kepulauan-riau": { nama: "Kepulauan Riau" },
    "jambi": { nama: "Jambi" },
    "sumatera-selatan": { nama: "Sumatera Selatan" },
    "bengkulu": { nama: "Bengkulu" },
    "lampung": { nama: "Lampung" },
    "bangka-belitung": { nama: "Kepulauan Bangka Belitung" },
    "dki-jakarta": { nama: "DKI Jakarta" },
    "banten": { nama: "Banten" },
    "jawa-barat": { nama: "Jawa Barat" },
    "jawa-tengah": { nama: "Jawa Tengah" },
    "di-yogyakarta": { nama: "DI Yogyakarta" },
    "jawa-timur": { nama: "Jawa Timur" },
    "bali": { nama: "Bali" },
    "nusa-tenggara-barat": { nama: "Nusa Tenggara Barat" },
    "nusa-tenggara-timur": { nama: "Nusa Tenggara Timur" },
    "kalimantan-barat": { nama: "Kalimantan Barat" },
    "kalimantan-tengah": { nama: "Kalimantan Tengah" },
    "kalimantan-selatan": { nama: "Kalimantan Selatan" },
    "kalimantan-timur": { nama: "Kalimantan Timur" },
    "kalimantan-utara": { nama: "Kalimantan Utara" },
    "sulawesi-utara": { nama: "Sulawesi Utara" },
    "gorontalo": { nama: "Gorontalo" },
    "sulawesi-tengah": { nama: "Sulawesi Tengah" },
    "sulawesi-barat": { nama: "Sulawesi Barat" },
    "sulawesi-selatan": { nama: "Sulawesi Selatan" },
    "sulawesi-tenggara": { nama: "Sulawesi Tenggara" },
    "maluku": { nama: "Maluku" },
    "maluku-utara": { nama: "Maluku Utara" },
    "papua": { nama: "Papua" },
    "papua-barat": { nama: "Papua Barat" },
    "papua-barat-daya": { nama: "Papua Barat Daya" },
    "papua-tengah": { nama: "Papua Tengah" },
    "papua-pegunungan": { nama: "Papua Pegunungan" },
    "papua-selatan": { nama: "Papua Selatan" }
};

const status = document.getElementById("status");

setTimeout(() => {
    const provinsiElements = document.querySelectorAll(".provinsi");
    
    if (provinsiElements.length === 0) return;

    provinsiElements.forEach(el => {
        el.setAttribute("role", "button");

        // KETIKA DIKLIK: Buka di tab yang sama
        el.addEventListener("click", function() {
            const idProvinsi = this.id;
            const urlTujuan = `{{ url('/budaya') }}/${idProvinsi}`; 
            
            // PERHATIKAN BARIS INI: Menggunakan location.href, bukan window.open
            window.location.href = urlTujuan; 
        });

        // KETIKA KURSOR DIARAHKAN (HOVER): Tampilkan nama provinsi
        el.addEventListener("mouseenter", function() {
            const data = dataBudaya[this.id];
            if (data) {
                status.innerHTML = "Klik untuk melihat budaya <b>" + data.nama + "</b>.";
                status.classList.add("bg-green-100");
            }
        });

        // KETIKA KURSOR KELUAR: Kembalikan teks semula
        el.addEventListener("mouseleave", function() {
            status.innerHTML = "👋 Selamat datang! Pilih provinsi pada peta.";
            status.classList.remove("bg-green-100");
        });
    });
}, 100);
</script>
@endpush